def _login_page(ir: FrontendIR) -> str:
    return f"""\
{_HEADER.format(version=ir.generator_version, hash=ir.spec_hash)}
"use client";

import {{ Suspense, useState }} from "react";
import {{ useRouter, useSearchParams }} from "next/navigation";
import {{ Button }} from "@/components/ui/button";
import {{ Input }} from "@/components/ui/input";
import {{ Label }} from "@/components/ui/label";
import {{ Card, CardContent, CardDescription, CardHeader, CardTitle }} from "@/components/ui/card";
import * as authApi from "@/generated/api/auth";
import type {{ AuthResponse }} from "@/generated/types";

function safeInternalPath(raw: string | null): string | null {{
  if (!raw || !raw.startsWith("/")) return null;
  if (raw.startsWith("//") || raw.includes("://")) return null;
  return raw;
}}

function homeForUser(res: AuthResponse): string {{
  if (res.role === "admin") return "/admin";
  return "/dashboard";
}}

function LoginForm() {{
  const router = useRouter();
  const searchParams = useSearchParams();
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  async function handleSubmit(e: React.FormEvent) {{
    e.preventDefault();
    setError(null);
    setLoading(true);
    try {{
      const res = await authApi.login({{ email, password }});
      const next = safeInternalPath(searchParams.get("next"));
      router.push(next ?? homeForUser(res));
    }} catch (err: unknown) {{
      setError(err instanceof Error ? err.message : "Login failed");
    }} finally {{
      setLoading(false);
    }}
  }}

  return (
    <Card>
      <CardHeader className="text-center">
        <CardTitle className="text-2xl">{ir.marketplace.name}</CardTitle>
        <CardDescription>Sign in to your account</CardDescription>
      </CardHeader>
      <CardContent>
        {{/* AGENT_FILL:login_form:start */}}
        <form onSubmit={{handleSubmit}} className="space-y-4">
          {{error && (
            <div className="rounded-md bg-destructive/10 p-3 text-sm text-destructive">
              {{error}}
            </div>
          )}}
          <div className="space-y-2">
            <Label htmlFor="email">Email</Label>
            <Input
              id="email"
              type="email"
              value={{email}}
              onChange={{(e) => setEmail(e.target.value)}}
              required
            />
          </div>
          <div className="space-y-2">
            <Label htmlFor="password">Password</Label>
            <Input
              id="password"
              type="password"
              value={{password}}
              onChange={{(e) => setPassword(e.target.value)}}
              required
            />
          </div>
          <Button type="submit" className="w-full" disabled={{loading}}>
            {{loading ? "Signing in..." : "Sign In"}}
          </Button>
        </form>
        {{/* AGENT_FILL:login_form:end */}}
      </CardContent>
    </Card>
  );
}}

export default function LoginPage() {{
  return (
    <Suspense fallback={{null}}>
      <LoginForm />
    </Suspense>
  );
}}
"""


